mapper.select:
SELECT LIST_LIMIT.* FROM ( SELECT @ROWNUM:= @ROWNUM + 1 AS rownum, LIST.* FROM ( SELECT *, (SUM(result_tb.calculate_deposit_amount) OVER(order by result_tb.calc_date) - SUM(result_tb.act_principal) OVER(order by result_tb.calc_date)) AS cal_balance FROM ( SELECT mrp.mbid, '입금' AS status, DATE_FORMAT(mrp.calculate_deposit_date, '%Y-%m-%d 00:59:59') AS calc_date, mrp.calculate_deposit_amount, '' AS act_principal, '' AS usage_fee, '' AS remittance_fee, '' AS balance_deposit_date , '' AS balance_remittance_amount, 0 AS deposit_amount FROM MONEYBANK_REDEM_PROVISION mrp WHERE mrp.mbid = #{mbid} UNION SELECT mrc.mbid, '상환', DATE_FORMAT(mrd.deposit_date, '%Y-%m-%d 23:59:59'), '', mrc.act_principal, mrc.usage_fee, mrc.remittance_fee, mrc.balance_deposit_date, mrc.balance_remittance_amount, SUM(mrd.deposit_amount) FROM MONEYBANK_REDEM_CALCULATE mrc LEFT JOIN MONEYBANK_REDEM_DEPOSIT mrd ON mrc.settlement_code = mrd.settlement_code WHERE mrc.mbid = #{mbid} GROUP BY mrd.deposit_date ) result_tb ORDER BY result_tb.calc_date DESC ) LIST, (SELECT @ROWNUM:=0) r
WHERE LIST.calc_date >= #{fromDate} AND LIST.calc_date <= #{toDate}
AND LIST.status IN (#{status})
)LIST_LIMIT LIMIT ${current_data}, ${data_limit}
